    passage:`<ruby>観光地<rt>かんこうち</rt></ruby>では、観光客を増やすために有名な場所や食べ物を積極的に紹介することが多い。しかし最近では、その地域で暮らす人々の日常生活に関心を持つ観光客も増えているという。例えば、地元の市場を見学したり、地域の人と交流したりする体験が人気を集めている。専門家は、「観光とは特別なものを見ることだけではなく、その土地の暮らしを知ることでもある」と述べている。`,

