    passage:`最近はインターネットで簡単に多くの情報を得られるようになった。そのため、分からないことがあればすぐに検索する人も多い。しかし、ある教育者は「情報を見つける力」と同じくらい、「情報を疑う力」も重要だと述べている。なぜなら、インターネット上には正しい情報だけでなく、間違った情報も存在するからである。また、同じ出来事について異なる意見が示されることもある。そのため、情報を集めるだけでなく、それを比較しながら考えることが求められている。`,

