夏休みに実施する合宿についてお知らせします。

今年の合宿は8月20日から22日までの3日間、長野県で行います。当初は2泊3日の予定でしたが、宿泊施設の都合により日程を1日後ろへ変更しました。そのため、以前配布した案内とは日付が異なっていますので注意してください。

