    passage:`ある自治体では、<ruby>防災<rt>ぼうさい</rt></ruby>意識を高めるために避難訓練への参加を呼びかけている。しかし、毎年同じ内容の訓練を行っても参加者が増えないという課題があった。

そこで今年は、実際の災害を想定した体験型の訓練を取り入れた。参加者は避難経路を歩いて確認したり、非常食を試食したりすることができる。その結果、例年より多くの住民が参加しただけでなく、「自分にも関係のある問題だと感じた」という感想も多く寄せられた。

担当者は、防災知識を伝えるだけではなく、住民自身が災害を身近な問題として考えられるようにすることが重要だと話している。`,

