    passage:`近年、多くの学校でタブレット端末が利用されるようになった。以前は紙の教材が中心だったが、現在ではデジタル教材を活用する場面も増えている。

タブレットには、資料をすぐに共有できることや、学習記録を簡単に確認できることなどの利点がある。一方で、機器の操作に慣れていない生徒や、画面を見る時間が長くなることを心配する声もある。

このような状況の中で教育関係者が強調しているのは、タブレットを導入すること自体が目的ではないという点である。大切なのは、それによって学習がどのように改善されるかであり、紙かデジタルかという単純な対立ではないというのである。`,

