しかし、オンライン化には利点だけでなく課題もある。例えば、会議では発言のタイミングが難しくなったり、相手の細かな表情が分かりにくくなったりすることがある。また、新しく組織に入った人は、雑談や偶然の出会いが少ないため、人間関係を築きにくいと感じる場合もある。

一方で、対面でなければできないことばかりでもない。オンラインで十分に効果を発揮できる活動も存在する。重要なのは、対面とオンラインのどちらが優れているかを議論することではなく、それぞれの特徴を理解した上で適切に使い分けることである。

