近年、「好きなことを仕事にするべきだ」という考え方を耳にする機会が増えている。実際、以前と比べて働き方の選択肢は広がり、個人が自分の興味や得意分野を生かしながら働くことも可能になってきた。そのため、自分の好きなことを職業にしたいと考える人は少なくない。

確かに、好きなことであれば意欲を持って取り組みやすい。困難に直面しても努力を続けやすく、学習にも積極的になれるだろう。また、仕事そのものにやりがいを感じやすいという利点もある。

しかし、好きなことを仕事にすることには難しさもある。例えば、趣味として楽しんでいた時には自由に取り組めたことでも、仕事になると納期や責任が発生する。結果を求められるようになれば、以前と同じ気持ちでは続けられなくなるかもしれない。

さらに、最初は特別な興味を持っていなかった仕事であっても、経験を重ねる中で面白さを感じるようになる場合もある。実際、多くの社会人が「仕事を始めた時は好きではなかったが、続けるうちに好きになった」と語っている。

