近年、<ruby>食品ロス<rt>しょくひんロス</rt></ruby>への関心が高まっている。食品ロスとは、本来食べられるにもかかわらず廃棄されてしまう食品のことである。

食品ロスが問題視される理由の一つは、資源の無駄につながるからである。食品を生産するためには水やエネルギー、労働力など多くの資源が必要となる。しかし、それらが十分に利用されないまま廃棄されてしまえば、大きな損失となる。

また、環境への影響も無視できない。廃棄された食品を処理する過程では二酸化炭素が排出されるため、食品ロスの削減は環境保護にもつながると考えられている。

食品ロスは企業だけの問題ではない。家庭でも、買い過ぎや保存方法の問題によって食品が捨てられることがある。そのため、必要な量だけ購入することや、食材を計画的に利用することが重要だと言われている。

