私たちは日常生活の中で、何かを選ぶたびに比較を行っている。商品を購入する時だけでなく、学校や仕事、人間関係について考える時にも比較は行われる。

比較そのものは悪いことではない。複数の選択肢を検討することで、自分にとってより適切な判断ができる場合もある。しかし問題は、比較が目的になってしまうことである。

例えば、他人の成果ばかりを見ていると、自分の進歩に気づきにくくなる。以前の自分と比べれば成長しているにもかかわらず、より優れた人と比較することで自信を失ってしまうこともある。

