    passage:`【評論】

近年、多くの企業や学校で「創造性」の重要性が語られるようになっている。かつては、与えられた手順を正確に実行する能力が重視される場面が多かった。しかし、技術の発展によって単純な作業の一部が自動化されるようになり、人間にはこれまで以上に新しい発想や柔軟な考え方が求められるようになった。

ところが、「創造的な人」と聞くと、多くの人は特別な才能を持った芸術家や発明家を思い浮かべるかもしれない。そのため、自分には創造性がないと考える人も少なくない。しかし専門家の中には、創造性とは一部の人だけが持つ特別な能力ではなく、誰もが伸ばすことのできる力だと主張する人もいる。

例えば、新しい製品の開発だけが創造性ではない。日常生活の中で問題を解決する工夫や、仕事の進め方を改善するための提案も創造性の一種である。つまり創造性とは、全く新しいものを生み出すことだけではなく、既存の知識や経験を新しい形で結び付ける力だと言える。

また、創造性は一人で生まれるとは限らない。異なる背景や価値観を持つ人々との対話の中から新しい発想が生まれることもある。そのため、多様な意見を受け入れる環境は創造性を高める上で重要だと考えられている。

私は、創造性とは特別な才能ではなく、物事を別の角度から見ようとする姿勢だと思う。変化の激しい時代だからこそ、そのような姿勢がこれまで以上に求められているのではないだろうか。`,

