例えば、同じ試験を受けた2人の学生がいたとする。1人は高得点を取ったが十分な勉強をしていなかった。もう1人は目標点数には届かなかったものの、以前より大きく成績を伸ばしていた。この場合、どちらを高く評価するべきだろうか。

