しかしある旅行で列車が遅れ、予定どおりに進めなくなったことがある。当初は残念に思ったが、そのおかげで予定にはなかった町を訪れることになった。

その町には小さな市場があり、地元の人々と話をする機会もあった。結果として、その旅行で最も印象に残ったのは当初計画していた観光地ではなく、その偶然の出会いだったのである。

